import {ATTR,HEROES,trainingOptions} from './expedition-data.mjs';
import {experienceLedger} from './expedition-growth.mjs';
import {experienceView} from './expedition-progression-view.mjs';
const targets=Object.freeze({overview:'#growth-navigation',skills:'#growth-skills',attributes:'#growth-attributes',course:'.growth-card',plan:'.training-plan',experience:'#growth-experience'});
const detailKeys=new Set(['experience','course-rules','attributes',...Object.keys(ATTR).flatMap(k=>['attr:'+k,'preview:attr:'+k]),...HEROES.flatMap(h=>Object.entries(trainingOptions(h.id)).filter(([,o])=>o.kind!=='attribute').flatMap(([key])=>['use:'+key,'impact:'+key]))]);
export function growthNavigationView(){return '<nav id="growth-navigation" class="growth-navigation" aria-label="角色成长定位" tabindex="-1"><p>先选择队员，再定位要调整的内容。</p>'+[['skills','普通技能与防御'],['attributes','属性培养'],['plan','培养草案与试演'],['course','课程与进阶'],['experience','经验去向']].map(([key,label])=>`<button type="button" data-growth-jump="${key}">${label}</button>`).join('')+'</nav>';}
export function growthExperienceView(member){const l=experienceLedger(member);return `<details id="growth-experience" class="growth-experience" data-growth-detail="experience"><summary>经验去向 · 可用 ${l.available} · 累计 ${l.earned}</summary>${experienceView(member)}</details>`;}
export function captureGrowthDetails(root){const state=Object.create(null);for(const d of root.querySelectorAll('[data-growth-detail]'))if(detailKeys.has(d.dataset.growthDetail))state[d.dataset.growthDetail]=d.open===true;return state;}
export function restoreGrowthDetails(root,state){for(const d of root.querySelectorAll('[data-growth-detail]'))if(detailKeys.has(d.dataset.growthDetail)&&Object.hasOwn(state,d.dataset.growthDetail))d.open=state[d.dataset.growthDetail]===true;}
export function jumpGrowth(root,key){if(!Object.hasOwn(targets,key))return false;const target=root.querySelector(targets[key]);if(!target)return false;if(target.tagName==='DETAILS')target.open=true;const focus=target.tagName==='DETAILS'?target.querySelector('summary'):target;if(!focus)return false;if(target.tagName!=='DETAILS')focus.tabIndex=-1;const tabs=root.querySelector('.guild-tabs'),sticky=tabs&&root.ownerDocument?.defaultView?.getComputedStyle(tabs).position==='sticky';target.style.scrollMarginTop=(sticky?tabs.getBoundingClientRect().height+12:12)+'px';focus.focus({preventScroll:true});target.scrollIntoView({block:'start',behavior:'auto'});return true;}
export function focusGrowthAction(root,action,key){if(!['learn','untrain'].includes(action)||typeof key!=='string')return false;const button=[...root.querySelectorAll('[data-'+action+']')].find(b=>b.dataset[action]===key);if(!button)return false;const target=button.disabled?button.closest('.training-row,[data-attribute-row]'):button;if(!target)return false;if(target!==button)target.tabIndex=-1;target.focus({preventScroll:true});return true;}
